/**
 * Python-flavoured numbers.
 *
 * `json.loads` in CPython yields two distinct number types: `int` for literals
 * without a fraction or exponent part, and `float` for everything else. Several
 * validation keywords observe that difference (draft-3/4 `type: "integer"`,
 * `multipleOf`), and `int` is arbitrary precision, so a plain JS `number`
 * cannot stand in for both. Every parsed JSON number is therefore wrapped.
 */

export class PyNum {
  constructor(num, isInt, big) {
    this.num = num;
    this.isInt = isInt;
    this.big = big === undefined ? null : big;
  }

  valueOf() {
    return this.num;
  }
}

export function makeInt(big) {
  return new PyNum(Number(big), true, big);
}

export function makeFloat(num) {
  return new PyNum(num, false, null);
}

export function isPyNum(value) {
  return value instanceof PyNum;
}

/** True when both operands are exact integers we can compare without loss. */
function bothBig(a, b) {
  return a.big !== null && b.big !== null;
}

export function numLt(a, b) {
  if (bothBig(a, b)) return a.big < b.big;
  return a.num < b.num;
}

export function numLe(a, b) {
  if (bothBig(a, b)) return a.big <= b.big;
  return a.num <= b.num;
}

export function numGt(a, b) {
  if (bothBig(a, b)) return a.big > b.big;
  return a.num > b.num;
}

export function numGe(a, b) {
  if (bothBig(a, b)) return a.big >= b.big;
  return a.num >= b.num;
}

/** `==` between two Python numbers: `1 == 1.0` holds. */
export function numEq(a, b) {
  if (bothBig(a, b)) return a.big === b.big;
  return a.num === b.num;
}

/** Python `isinstance(x, int)` — bools are excluded upstream. */
export function isPyInt(value) {
  return value instanceof PyNum && value.isInt;
}

/** Python `float.is_integer()`, false for inf/nan. */
export function isIntegralFloat(value) {
  return Number.isFinite(value.num) && Math.trunc(value.num) === value.num;
}

/**
 * Truthiness of Python's `instance % dB` for the integral `multipleOf` branch.
 * Python's modulo takes the sign of the divisor while JS takes the dividend's,
 * but a zero result is a zero result either way, so only that matters here.
 */
export function remainderIsNonZero(instance, dB) {
  if (bothBig(instance, dB)) {
    if (dB.big === 0n) throw new Error('integer division or modulo by zero');
    return instance.big % dB.big !== 0n;
  }
  if (dB.num === 0) throw new Error('integer division or modulo by zero');
  return instance.num % dB.num !== 0;
}

/** A stable key used for hashing numbers inside `uniqueItems`. */
export function numKey(value) {
  if (value.big !== null) return `n:${value.big.toString()}`;
  if (Number.isFinite(value.num) && Math.trunc(value.num) === value.num) {
    // 1 and 1.0 must collide.
    return `n:${BigInt(value.num).toString()}`;
  }
  return `n:${value.num}`;
}

