/**
 * A `json.loads`-compatible parser.
 *
 * `JSON.parse` is unusable here for two reasons: it collapses `1` and `1.0`
 * into the same value, and it rebuilds objects as plain JS objects, which
 * silently reorder integer-like keys. CPython preserves both distinctions, so
 * this parser produces `Map`s for objects and `PyNum`s for numbers.
 *
 * Deviations from `JSON.parse` that mirror CPython: `NaN`, `Infinity` and
 * `-Infinity` are accepted as literals.
 */

import { makeFloat, makeInt } from './pynum.mjs';

const WHITESPACE = new Set([' ', '\t', '\n', '\r']);

export class JSONDecodeError extends Error {
  constructor(msg, doc, pos) {
    const lineno = doc.slice(0, pos).split('\n').length;
    const colno = pos - doc.lastIndexOf('\n', pos - 1);
    super(`${msg}: line ${lineno} column ${colno} (char ${pos})`);
    this.name = 'JSONDecodeError';
    this.pos = pos;
  }
}

const ESCAPES = {
  '"': '"',
  '\\': '\\',
  '/': '/',
  b: '\b',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
};

class Parser {
  constructor(text) {
    this.s = text;
    this.i = 0;
  }

  error(msg, pos) {
    return new JSONDecodeError(msg, this.s, pos === undefined ? this.i : pos);
  }

  skipWhitespace() {
    while (this.i < this.s.length && WHITESPACE.has(this.s[this.i])) this.i += 1;
  }

  parseValue() {
    if (this.i >= this.s.length) throw this.error('Expecting value');
    const ch = this.s[this.i];

    if (ch === '{') return this.parseObject();
    if (ch === '[') return this.parseArray();
    if (ch === '"') return this.parseString();

    if (this.s.startsWith('true', this.i)) return (this.i += 4, true);
    if (this.s.startsWith('false', this.i)) return (this.i += 5, false);
    if (this.s.startsWith('null', this.i)) return (this.i += 4, null);
    if (this.s.startsWith('NaN', this.i)) return (this.i += 3, makeFloat(NaN));
    if (this.s.startsWith('Infinity', this.i)) return (this.i += 8, makeFloat(Infinity));
    if (this.s.startsWith('-Infinity', this.i)) return (this.i += 9, makeFloat(-Infinity));

    const num = this.tryParseNumber();
    if (num !== null) return num;
    throw this.error('Expecting value');
  }

  tryParseNumber() {
    const start = this.i;
    let j = this.i;
    if (this.s[j] === '-') j += 1;

    const digitsStart = j;
    if (this.s[j] === '0') {
      j += 1;
    } else {
      while (j < this.s.length && this.s[j] >= '0' && this.s[j] <= '9') j += 1;
    }
    if (j === digitsStart) return null;

    let isInt = true;
    if (this.s[j] === '.') {
      const fracStart = j + 1;
      let k = fracStart;
      while (k < this.s.length && this.s[k] >= '0' && this.s[k] <= '9') k += 1;
      if (k > fracStart) {
        isInt = false;
        j = k;
      }
    }
    if (this.s[j] === 'e' || this.s[j] === 'E') {
      let k = j + 1;
      if (this.s[k] === '+' || this.s[k] === '-') k += 1;
      const expStart = k;
      while (k < this.s.length && this.s[k] >= '0' && this.s[k] <= '9') k += 1;
      if (k > expStart) {
        isInt = false;
        j = k;
      }
    }

    const raw = this.s.slice(start, j);
    this.i = j;
    return isInt ? makeInt(BigInt(raw)) : makeFloat(Number(raw));
  }

  parseString() {
    // Caller guarantees the opening quote.
    this.i += 1;
    let out = '';
    for (;;) {
      if (this.i >= this.s.length) throw this.error('Unterminated string starting at');
      const ch = this.s[this.i];

      if (ch === '"') {
        this.i += 1;
        return out;
      }
      if (ch === '\\') {
        this.i += 1;
        const esc = this.s[this.i];
        if (esc === undefined) throw this.error('Unterminated string starting at');
        if (esc === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw this.error('Invalid \\uXXXX escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.i += 5;
        } else if (Object.prototype.hasOwnProperty.call(ESCAPES, esc)) {
          out += ESCAPES[esc];
          this.i += 1;
        } else {
          throw this.error(`Invalid \\escape: ${JSON.stringify(esc)}`);
        }
        continue;
      }
      // strict=True in CPython rejects raw control characters.
      if (ch < ' ') throw this.error(`Invalid control character ${JSON.stringify(ch)} at`);
      out += ch;
      this.i += 1;
    }
  }

  parseObject() {
    this.i += 1;
    const result = new Map();
    this.skipWhitespace();
    if (this.s[this.i] === '}') {
      this.i += 1;
      return result;
    }
    for (;;) {
      this.skipWhitespace();
      if (this.s[this.i] !== '"') throw this.error('Expecting property name enclosed in double quotes');
      const key = this.parseString();
      this.skipWhitespace();
      if (this.s[this.i] !== ':') throw this.error("Expecting ':' delimiter");
      this.i += 1;
      this.skipWhitespace();
      // Re-inserting an existing key keeps its original position, matching dict.
      result.set(key, this.parseValue());
      this.skipWhitespace();
      const ch = this.s[this.i];
      if (ch === ',') {
        this.i += 1;
        continue;
      }
      if (ch === '}') {
        this.i += 1;
        return result;
      }
      throw this.error("Expecting ',' delimiter");
    }
  }

  parseArray() {
    this.i += 1;
    const result = [];
    this.skipWhitespace();
    if (this.s[this.i] === ']') {
      this.i += 1;
      return result;
    }
    for (;;) {
      this.skipWhitespace();
      result.push(this.parseValue());
      this.skipWhitespace();
      const ch = this.s[this.i];
      if (ch === ',') {
        this.i += 1;
        continue;
      }
      if (ch === ']') {
        this.i += 1;
        return result;
      }
      throw this.error("Expecting ',' delimiter");
    }
  }
}

export function loads(text) {
  const parser = new Parser(text);
  parser.skipWhitespace();
  const value = parser.parseValue();
  parser.skipWhitespace();
  if (parser.i !== text.length) throw parser.error('Extra data');
  return value;
}

/**
 * Lift a literal JS structure (used for the bundled metaschemas) into the same
 * representation `loads` produces.
 */
export function fromLiteral(value) {
  if (Array.isArray(value)) return value.map(fromLiteral);
  if (typeof value === 'number') {
    return Number.isInteger(value) ? makeInt(BigInt(value)) : makeFloat(value);
  }
  if (value !== null && typeof value === 'object') {
    const map = new Map();
    for (const [k, v] of Object.entries(value)) map.set(k, fromLiteral(v));
    return map;
  }
  return value;
}

