/**
 * Structural helpers over the parsed-JSON representation: `Map` for objects,
 * `Array` for arrays, `PyNum` for numbers, JS primitives for the rest.
 */

import { isPyNum, numEq, numKey } from './pynum.mjs';

export function isObject(value) {
  return value instanceof Map;
}

export function isArray(value) {
  return Array.isArray(value);
}

export function isString(value) {
  return typeof value === 'string';
}

export function isBool(value) {
  return typeof value === 'boolean';
}

export function isNull(value) {
  return value === null;
}

export function get(map, key, fallback) {
  if (!isObject(map)) return fallback;
  return map.has(key) ? map.get(key) : fallback;
}

export function has(map, key) {
  return isObject(map) && map.has(key);
}

/** Python's `len(x)` for strings — code points, not UTF-16 units. */
export function codePointLength(str) {
  let n = 0;
  for (const _ of str) n += 1;
  return n;
}

/**
 * `_utils.ensure_list`: a bare string becomes a one-element list, anything else
 * is passed through.
 */
export function ensureList(value) {
  return isString(value) ? [value] : value;
}

/**
 * `_utils.equal`. Booleans are "unbooled" into their own domain so `True` never
 * compares equal to `1`, while `1 == 1.0` still holds.
 */
export function equal(one, two) {
  if (one === two) return true;
  if (isString(one) || isString(two)) return one === two;
  if (isArray(one) && isArray(two)) {
    if (one.length !== two.length) return false;
    return one.every((item, index) => equal(item, two[index]));
  }
  if (isObject(one) && isObject(two)) {
    if (one.size !== two.size) return false;
    for (const [key, value] of one) {
      if (!two.has(key)) return false;
      if (!equal(value, two.get(key))) return false;
    }
    return true;
  }
  if (isBool(one) || isBool(two)) return one === two;
  if (isPyNum(one) && isPyNum(two)) return numEq(one, two);
  return one === two;
}

/** `_utils.uniq` — reports whether every element is distinct under `equal`. */
export function uniq(container) {
  // Bucket by a cheap hash first so the quadratic fallback only runs on
  // genuine collisions.
  const buckets = new Map();
  for (const item of container) {
    const key = hashKey(item);
    const bucket = buckets.get(key);
    if (bucket === undefined) {
      buckets.set(key, [item]);
      continue;
    }
    if (bucket.some((other) => equal(other, item))) return false;
    bucket.push(item);
  }
  return true;
}

function hashKey(value) {
  if (value === null) return 'null';
  if (isBool(value)) return `b:${value}`;
  if (isString(value)) return `s:${value}`;
  if (isPyNum(value)) return numKey(value);
  if (isArray(value)) return `a:${value.length}`;
  if (isObject(value)) return `o:${value.size}`;
  return 'x';
}

