 * `_utils.equal`. Booleans are "unbooled" into their own domain so `True` never
 * compares equal to `1`, while `1 == 1.0` still holds.
 */
export function equal(one, two) {
  if (one === two) return true;
  if (isString(one) || isString(two)) return one === two;
  if (isArray(one) && isArray(two)) {
    if (one.length !== two.length) return false;
    return one.every((item, index) => equal(item, two[index]));
