export function uniq(container) {
  // Bucket by a cheap hash first so the quadratic fallback only runs on
  // genuine collisions.
  const buckets = new Map();
  for (const item of container) {
    const key = hashKey(item);
    const bucket = buckets.get(key);
    if (bucket === undefined) {
      buckets.set(key, [item]);
