/**
 * Translation of Python `re` patterns into JS `RegExp`.
 *
 * `pattern`, `patternProperties` and `propertyNames` are all specified in terms
 * of `re.search`, and the two flavours disagree in ways that change validation
 * outcomes:
 *
 *   - `$` in Python also matches immediately before a trailing newline.
 *   - `\d`, `\w` and friends are Unicode-aware in Python 3 but ASCII-only in JS.
 *   - Python spells named groups `(?P<x>...)` / `(?P=x)`, and supports
 *     `(?#comment)` and the `\A` / `\Z` / `\z` anchors.
 *   - Inline global flags `(?i)`, `(?s)`, `(?m)`, `(?x)`, `(?a)`.
 */

const cache = new Map();

class TranslationState {
  constructor() {
    this.flags = new Set();
    this.verbose = false;
    this.ascii = false;
  }
}

/**
 * Pull leading/inline global flag groups out of the pattern and record them.
 */
function extractGlobalFlags(pattern, state) {
  return pattern.replace(/\(\?([aiLmsux]+)\)/g, (_match, letters) => {
    for (const letter of letters) {
      if (letter === 'i' || letter === 's' || letter === 'm') state.flags.add(letter);
      else if (letter === 'x') state.verbose = true;
      else if (letter === 'a') state.ascii = true;
    }
    return '';
  });
}

/**
 * Rewrite the pattern body. `unicodeClasses` selects between Unicode property
 * escapes (requires the `u` flag) and JS's ASCII shorthands.
 */
function rewrite(pattern, state, unicodeClasses) {
  let out = '';
  let inClass = false;
  let i = 0;

  const digit = unicodeClasses ? '\\p{Nd}' : '\\d';
  const notDigit = unicodeClasses ? '[^\\p{Nd}]' : '\\D';
  const word = unicodeClasses ? '\\p{L}\\p{N}_' : 'A-Za-z0-9_';

  while (i < pattern.length) {
    const ch = pattern[i];

    if (ch === '\\') {
      const next = pattern[i + 1];
      i += 2;
      switch (next) {
        case 'A':
          out += inClass ? '\\x07' : '^';
          break;
        case 'Z':
        case 'z':
          out += inClass ? '\\x1a' : '(?![\\s\\S])';
          break;
        case 'd':
          out += inClass ? digit : unicodeClasses ? `[${digit}]` : '\\d';
          break;
        case 'D':
          out += inClass ? (unicodeClasses ? digit : '\\d') : notDigit;
          break;
        case 'w':
          out += inClass ? word : `[${word}]`;
          break;
        case 'W':
          out += inClass ? word : `[^${word}]`;
          break;
        default:
          if (next === undefined) throw new Error('bad escape (end of pattern)');
          out += `\\${next}`;
          break;
      }
      continue;
    }

    if (inClass) {
      if (ch === ']') inClass = false;
      out += ch;
      i += 1;
      continue;
    }

    if (ch === '[') {
      inClass = true;
      out += ch;
      i += 1;
      // A leading `]` (optionally after `^`) is a literal in both flavours,
      // but JS in Unicode mode needs it escaped.
      if (pattern[i] === '^') {
        out += '^';
        i += 1;
      }
      if (pattern[i] === ']') {
        out += '\\]';
        i += 1;
      }
      continue;
    }

    if (ch === '$') {
      // Python: end of string, or just before a final newline.
      out += state.flags.has('m') ? '$' : '(?=\\n?(?![\\s\\S]))';
      i += 1;
      continue;
    }

    if (ch === '(' && pattern[i + 1] === '?') {
      const third = pattern[i + 2];
      if (third === 'P') {
        const fourth = pattern[i + 3];
        if (fourth === '<') {
          out += '(?<';
          i += 4;
          continue;
        }
        if (fourth === '=') {
          const close = pattern.indexOf(')', i + 4);
          if (close === -1) throw new Error('unterminated group reference');
          out += `\\k<${pattern.slice(i + 4, close)}>`;
          i = close + 1;
          continue;
        }
      }
      if (third === '#') {
        const close = pattern.indexOf(')', i + 3);
        if (close === -1) throw new Error('missing ), unterminated comment');
        i = close + 1;
        continue;
      }
    }

    if (state.verbose) {
      if (ch === '#') {
        while (i < pattern.length && pattern[i] !== '\n') i += 1;
        continue;
      }
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f') {
        i += 1;
        continue;
      }
    }

    out += ch;
    i += 1;
  }

  return out;
}

/** Compile a Python pattern, memoised like `re`'s own cache. */
export function compile(pattern) {
  const cached = cache.get(pattern);
  if (cached !== undefined) {
    if (cached instanceof Error) throw cached;
    return cached;
  }

  let compiled;
  try {
    compiled = build(pattern);
  } catch (error) {
    const wrapped = error instanceof Error ? error : new Error(String(error));
    cache.set(pattern, wrapped);
    throw wrapped;
  }
  cache.set(pattern, compiled);
  return compiled;
}

function build(pattern) {
  const state = new TranslationState();
  const body = extractGlobalFlags(pattern, state);
  const flags = [...state.flags].join('');

  if (!state.ascii) {
    try {
      return new RegExp(rewrite(body, state, true), `${flags}u`);
    } catch {
      // Constructs that Annex B allows but Unicode mode rejects (a lone `{`,
      // `\-` outside a class, ...). Retry with the laxer dialect.
    }
  }
  return new RegExp(rewrite(body, state, false), flags);
}

/** `re.search(pattern, string)` as a boolean. */
export function search(pattern, string) {
  return compile(pattern).test(string);
}

