/**
 * Per-draft type checkers, matching `jsonschema._types`.
 *
 * The distinctions that matter:
 *   - booleans are never `number`/`integer`, and `0`/`1` are never `boolean`;
 *   - draft-3 and draft-4 require a genuine `int` for `"integer"`, so `1.0`
 *     fails, whereas draft-6 onwards accepts any float with no fractional part;
 *   - draft-3 has an extra `"any"` type.
 */

import { isArray, isBool, isNull, isObject, isString } from './jtypes.mjs';
import { isIntegralFloat, isPyInt, isPyNum } from './pynum.mjs';
import { UndefinedTypeCheck } from './errors.mjs';

const base = {
  array: isArray,
  boolean: isBool,
  integer: (instance) => isPyInt(instance),
  object: isObject,
  null: isNull,
  number: (instance) => isPyNum(instance),
  string: isString,
};

export class TypeChecker {
  constructor(checks) {
    this.checks = checks;
  }

  isType(instance, type) {
    const check = this.checks[type];
    if (check === undefined) throw new UndefinedTypeCheck(type);
    return check(instance);
  }

  redefine(extra) {
    return new TypeChecker({ ...this.checks, ...extra });
  }
}

export const draft3TypeChecker = new TypeChecker({ ...base, any: () => true });

export const draft4TypeChecker = new TypeChecker(base);

const integralNumber = (instance) =>
  isPyNum(instance) && (instance.isInt || isIntegralFloat(instance));

export const draft6TypeChecker = draft4TypeChecker.redefine({ integer: integralNumber });

export const draft7TypeChecker = draft6TypeChecker;
export const draft201909TypeChecker = draft6TypeChecker;
export const draft202012TypeChecker = draft6TypeChecker;

