/** URI helpers standing in for the pieces of `urllib.parse` that `referencing` uses. */

const URI_RE = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/;

function parse(uri) {
  const match = URI_RE.exec(uri);
  return {
    scheme: match[1],
    authority: match[2],
    path: match[3] === undefined ? '' : match[3],
    query: match[4],
    fragment: match[5],
  };
}

function removeDotSegments(path) {
  const out = [];
  for (const segment of path.split('/')) {
    if (segment === '.') continue;
    if (segment === '..') {
      if (out.length > 1) out.pop();
      continue;
    }
    out.push(segment);
  }
  let joined = out.join('/');
  if (path.endsWith('/.') || path.endsWith('/..')) joined += '/';
  return joined;
}

function compose({ scheme, authority, path, query, fragment }) {
  let result = '';
  if (scheme !== undefined) result += `${scheme}:`;
  if (authority !== undefined) result += `//${authority}`;
  result += path;
  if (query !== undefined) result += `?${query}`;
  if (fragment !== undefined) result += `#${fragment}`;
  return result;
}

/** RFC 3986 §5.3 reference resolution, i.e. `urllib.parse.urljoin`. */
export function urljoin(base, ref) {
  if (!base) return ref;
  if (!ref) return urldefrag(base)[0];

  const r = parse(ref);
  const b = parse(base);

  if (r.scheme !== undefined) {
    return compose({ ...r, path: removeDotSegments(r.path) });
  }

  const target = { scheme: b.scheme, fragment: r.fragment };
  if (r.authority !== undefined) {
    target.authority = r.authority;
    target.path = removeDotSegments(r.path);
    target.query = r.query;
    return compose(target);
  }

  target.authority = b.authority;
  if (r.path === '') {
    target.path = b.path;
    target.query = r.query !== undefined ? r.query : b.query;
  } else {
    if (r.path.startsWith('/')) {
      target.path = removeDotSegments(r.path);
    } else if (b.authority !== undefined && b.path === '') {
      target.path = removeDotSegments(`/${r.path}`);
    } else {
      const cut = b.path.lastIndexOf('/');
      const prefix = cut === -1 ? '' : b.path.slice(0, cut + 1);
      target.path = removeDotSegments(prefix + r.path);
    }
    target.query = r.query;
  }
  return compose(target);
}

/** `urllib.parse.urldefrag` → `[withoutFragment, fragment]`. */
export function urldefrag(uri) {
  const index = uri.indexOf('#');
  if (index === -1) return [uri, ''];
  return [uri.slice(0, index), uri.slice(index + 1)];
}

/** `urllib.parse.unquote` — percent-decoding, tolerant of stray `%`. */
export function unquote(text) {
  if (!text.includes('%')) return text;
  return text.replace(/(?:%[0-9a-fA-F]{2})+/g, (seq) => {
    try {
      return decodeURIComponent(seq);
    } catch {
      return seq;
    }
  });
}

