const V20 = 'https://json-schema.org/draft/2020-12/vocab/';
const RECURSIVE = { $recursiveAnchor: true };
const DYNAMIC = { $dynamicAnchor: 'meta' };

/** Every bundled document, keyed by the URI a `$ref` would use. */
export const METASCHEMA_LITERALS = new Map([
  ['http://json-schema.org/draft-03/schema', DRAFT03],
  ['http://json-schema.org/draft-04/schema', DRAFT04],
  ['http://json-schema.org/draft-06/schema', DRAFT06],
  ['http://json-schema.org/draft-07/schema', DRAFT07],

