  [`${D19}meta/meta-data`, metaDataVocabulary(D19, `${V19}meta-data`, RECURSIVE)],
  [`${D19}meta/format`, D19_FORMAT],
  [`${D19}meta/content`, contentVocabulary(D19, `${V19}content`, RECURSIVE, '$recursiveRef')],

  [`${D20}schema`, D20_SCHEMA],
  [`${D20}meta/core`, D20_CORE],
  [`${D20}meta/applicator`, D20_APPLICATOR],
