  [`${D20}meta/validation`, validationVocabulary(D20, `${V20}validation`, DYNAMIC)],
  [`${D20}meta/meta-data`, metaDataVocabulary(D20, `${V20}meta-data`, DYNAMIC)],
  [`${D20}meta/format-annotation`, D20_FORMAT_ANNOTATION],
