/**
 * A small stand-in for the `referencing` library: it indexes a schema's
 * subresources by `$id`/`id` and anchor, and resolves `$ref` targets against
 * the current base URI.
 */

import { Unresolvable } from './errors.mjs';
import { fromLiteral } from './json.mjs';
import { isArray, isObject, isString } from './jtypes.mjs';
import { METASCHEMA_LITERALS } from './metaschemas.mjs';
import { unquote, urldefrag, urljoin } from './uri.mjs';

/** How a given draft spells identifiers and anchors. */
export class Specification {
  constructor({ idKeyword, anchorFromId, anchorKeywords }) {
    this.idKeyword = idKeyword;
    // draft-04/06/07 spell a plain-name anchor as `"$id": "#name"`.
    this.anchorFromId = anchorFromId;
    this.anchorKeywords = anchorKeywords;
  }
}

export const SPEC_DRAFT3 = new Specification({
  idKeyword: 'id',
  anchorFromId: true,
  anchorKeywords: [],
});
export const SPEC_DRAFT4 = SPEC_DRAFT3;
export const SPEC_DRAFT6 = new Specification({
  idKeyword: '$id',
  anchorFromId: true,
  anchorKeywords: [],
});
export const SPEC_DRAFT7 = SPEC_DRAFT6;
export const SPEC_DRAFT201909 = new Specification({
  idKeyword: '$id',
  anchorFromId: false,
  anchorKeywords: ['$anchor', '$recursiveAnchor'],
});
export const SPEC_DRAFT202012 = new Specification({
  idKeyword: '$id',
  anchorFromId: false,
  anchorKeywords: ['$anchor', '$dynamicAnchor'],
});

const METASCHEMA_SPECS = [
  ['http://json-schema.org/draft-03/schema', SPEC_DRAFT3],
  ['http://json-schema.org/draft-04/schema', SPEC_DRAFT4],
  ['http://json-schema.org/draft-06/schema', SPEC_DRAFT6],
  ['http://json-schema.org/draft-07/schema', SPEC_DRAFT7],
  ['https://json-schema.org/draft/2019-09/', SPEC_DRAFT201909],
  ['https://json-schema.org/draft/2020-12/', SPEC_DRAFT202012],
];

function specForMetaschema(uri) {
  for (const [prefix, spec] of METASCHEMA_SPECS) {
    if (uri.startsWith(prefix)) return spec;
  }
  return SPEC_DRAFT202012;
}

export class Registry {
  constructor() {
    this.resources = new Map();
    this.anchors = new Map();
    this.dynamicAnchors = new Set();
  }

  addResource(uri, contents, spec) {
    this.resources.set(uri, { contents, baseUri: uri, spec });
    this.crawl(contents, uri, spec);
  }

  crawl(node, baseUri, spec) {
    if (isArray(node)) {
      for (const child of node) this.crawl(child, baseUri, spec);
      return;
    }
    if (!isObject(node)) return;

    let base = baseUri;
    const rawId = node.get(spec.idKeyword);
    if (isString(rawId)) {
      if (spec.anchorFromId && rawId.startsWith('#')) {
        if (rawId.length > 1) this.anchors.set(`${base}#${rawId.slice(1)}`, node);
      } else {
        base = urldefrag(urljoin(base, rawId))[0];
        if (!this.resources.has(base)) {
          this.resources.set(base, { contents: node, baseUri: base, spec });
        }
      }
    }

    for (const keyword of spec.anchorKeywords) {
      const value = node.get(keyword);
      if (!isString(value)) continue;
      const key = `${base}#${value}`;
      this.anchors.set(key, node);
      if (keyword === '$dynamicAnchor') this.dynamicAnchors.add(key);
    }

    for (const value of node.values()) this.crawl(value, base, spec);
  }

  /** Resolve a fragment-free URI, materialising a bundled metaschema if needed. */
  getResource(uri) {
    const found = this.resources.get(uri);
    if (found !== undefined) return found;

    const literal = METASCHEMA_LITERALS.get(uri);
    if (literal === undefined) return undefined;

    const spec = specForMetaschema(uri);
    this.addResource(uri, fromLiteral(literal), spec);
    return this.resources.get(uri);
  }
}

export class Resolver {
  constructor(registry, baseUri, previous = []) {
    this.registry = registry;
    this.baseUri = baseUri;
    // Base URIs left behind by earlier lookups, innermost last.
    this.previous = previous;
  }

  /** The dynamic scope, innermost first — the order `$recursiveRef` walks. */
  dynamicScope() {
    return [...this.previous].reverse().filter((uri) => uri !== '');
  }

  lookup(ref) {
    const target = urljoin(this.baseUri, ref);
    const [uri, rawFragment] = urldefrag(target);

    const resource = this.registry.getResource(uri);
    if (resource === undefined) throw new Unresolvable(ref);

    const fragment = unquote(rawFragment);
    if (fragment === '') return this.resolved(resource.contents, resource.baseUri);

    if (fragment.startsWith('/')) {
      const { contents, baseUri } = this.walkPointer(resource, fragment, ref);
      return this.resolved(contents, baseUri);
    }

    const anchored = this.registry.anchors.get(`${uri}#${fragment}`);
    if (anchored === undefined) throw new Unresolvable(ref);
    return this.resolved(anchored, uri);
  }

  walkPointer(resource, pointer, ref) {
    let contents = resource.contents;
    let baseUri = resource.baseUri;
    const { spec } = resource;

    for (const rawSegment of pointer.slice(1).split('/')) {
      if (isArray(contents)) {
        const index = Number.parseInt(rawSegment, 10);
        contents = Number.isNaN(index) ? undefined : contents[index];
      } else if (isObject(contents)) {
        const key = rawSegment.split('~1').join('/').split('~0').join('~');
        contents = contents.has(key) ? contents.get(key) : undefined;
      } else {
        contents = undefined;
      }
      if (contents === undefined) throw new Unresolvable(ref);

      if (isObject(contents)) {
        const rawId = contents.get(spec.idKeyword);
        if (isString(rawId) && !(spec.anchorFromId && rawId.startsWith('#'))) {
          baseUri = urldefrag(urljoin(baseUri, rawId))[0];
        }
      }
    }
    return { contents, baseUri };
  }

  resolved(contents, baseUri) {
    return {
      contents,
      resolver: new Resolver(this.registry, baseUri, [...this.previous, this.baseUri]),
    };
  }
}

/** Build the root resolver for a schema document, mirroring `resolver_with_root`. */
export function resolverForRoot(schema, spec) {
  const registry = new Registry();
  let uri = '';
  if (isObject(schema)) {
    const rawId = schema.get(spec.idKeyword);
    if (isString(rawId) && !(spec.anchorFromId && rawId.startsWith('#'))) {
      uri = urldefrag(rawId)[0];
    }
  }
  registry.addResource(uri, schema, spec);
  return new Resolver(registry, uri);
}

