/**
 * Keyword implementations shared by the modern drafts (`jsonschema._keywords`).
 *
 * Each keyword is a generator yielding `ValidationError`s. The number of errors
 * a keyword yields is observable, so the fan-out matters as much as the verdict:
 * `properties` yields one error per failing property, while
 * `additionalProperties: false` yields a single error naming all the extras.
 */

import { ValidationError, UnknownType } from '../errors.mjs';
import {
  codePointLength,
  ensureList,
  equal,
  get,
  has,
  isArray,
  isObject,
  isString,
  uniq,
} from '../jtypes.mjs';
import {
  isIntegralFloat,
  isPyNum,
  numGe,
  numGt,
  numLe,
  numLt,
  remainderIsNonZero,
} from '../pynum.mjs';
import { search } from '../pyre.mjs';

const PLAIN = (value) => (isPyNum(value) ? value.num : value);

export function* type(validator, types, instance, schema) {
  const wanted = ensureList(types);
  for (const candidate of wanted) {
    // Python's `any()` short-circuits, so an unknown type name after a match is
    // never reached — and therefore never raises.
    if (validator.isType(instance, candidate)) return;
  }
  yield new ValidationError(`${describe(instance)} is not of type ${wanted.join(', ')}`);
}

export function* enum_(validator, enums, instance, schema) {
  for (const each of enums) {
    if (equal(each, instance)) return;
  }
  yield new ValidationError(`${describe(instance)} is not one of the enumerated values`);
}

export function* const_(validator, value, instance, schema) {
  if (!equal(value, instance)) {
    yield new ValidationError(`${describe(value)} was expected`);
  }
}

/* --------------------------------------------------------------- numbers */

export function* multipleOf(validator, dB, instance, schema) {
  if (!validator.isType(instance, 'number')) return;

  let failed;
  if (!dB.isInt) {
    const quotient = instance.num / dB.num;
    // CPython raises OverflowError from int(inf); jsonschema treats that as a
    // failure rather than propagating it.
    failed = !Number.isFinite(quotient) || Math.trunc(quotient) !== quotient;
  } else {
    failed = remainderIsNonZero(instance, dB);
  }
  if (failed) {
    yield new ValidationError(`${describe(instance)} is not a multiple of ${PLAIN(dB)}`);
  }
}

export function* minimum(validator, value, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (numLt(instance, value)) {
    yield new ValidationError(`${describe(instance)} is less than the minimum of ${PLAIN(value)}`);
  }
}

export function* maximum(validator, value, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (numGt(instance, value)) {
    yield new ValidationError(`${describe(instance)} is greater than the maximum of ${PLAIN(value)}`);
  }
}

export function* exclusiveMinimum(validator, value, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (numLe(instance, value)) {
    yield new ValidationError(
      `${describe(instance)} is less than or equal to the minimum of ${PLAIN(value)}`,
    );
  }
}

export function* exclusiveMaximum(validator, value, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (numGe(instance, value)) {
    yield new ValidationError(
      `${describe(instance)} is greater than or equal to the maximum of ${PLAIN(value)}`,
    );
  }
}

/* --------------------------------------------------------------- strings */

export function* minLength(validator, value, instance, schema) {
  if (!validator.isType(instance, 'string')) return;
  if (codePointLength(instance) < value.num) {
    yield new ValidationError(`${describe(instance)} is too short`);
  }
}

export function* maxLength(validator, value, instance, schema) {
  if (!validator.isType(instance, 'string')) return;
  if (codePointLength(instance) > value.num) {
    yield new ValidationError(`${describe(instance)} is too long`);
  }
}

export function* pattern(validator, patrn, instance, schema) {
  if (!validator.isType(instance, 'string')) return;
  if (!search(patrn, instance)) {
    yield new ValidationError(`${describe(instance)} does not match ${patrn}`);
  }
}

/** `format` without a format checker is a no-op, which is the default. */
export function* format(validator, formatName, instance, schema) {
  if (validator.formatChecker === null || validator.formatChecker === undefined) return;
  yield* validator.formatChecker.check(instance, formatName);
}

/* ---------------------------------------------------------------- arrays */

export function* minItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  if (instance.length < value.num) {
    yield new ValidationError(`${describe(instance)} is too short`);
  }
}

export function* maxItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  if (instance.length > value.num) {
    yield new ValidationError(`${describe(instance)} is too long`);
  }
}

export function* uniqueItems(validator, value, instance, schema) {
  if (value && validator.isType(instance, 'array') && !uniq(instance)) {
    yield new ValidationError(`${describe(instance)} has non-unique elements`);
  }
}

export function* prefixItems(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const count = Math.min(instance.length, value.length);
  for (let index = 0; index < count; index += 1) {
    yield* validator.descend(instance[index], value[index], index, index);
  }
}

/** 2020-12 `items`: applies to whatever `prefixItems` did not cover. */
export function* items(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  const prefix = get(schema, 'prefixItems', []).length;
  const total = instance.length;
  const extra = total - prefix;
  if (extra <= 0) return;

  if (value === false) {
    yield new ValidationError(`Expected at most ${prefix} items but found ${extra} extra`);
    return;
  }
  for (let index = prefix; index < total; index += 1) {
    yield* validator.descend(instance[index], value, index);
  }
}

export function* contains(validator, value, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  const minContains = numberOption(schema, 'minContains', 1);
  const maxContains = numberOption(schema, 'maxContains', instance.length);

  let matches = 0;
  const sub = validator.evolve(value);
  for (const each of instance) {
    if (!sub.isValid(each)) continue;
    matches += 1;
    if (matches > maxContains) {
      yield new ValidationError(
        `Too many items match the given schema (expected at most ${maxContains})`,
      );
      return;
    }
  }
  if (matches < minContains) {
    yield new ValidationError(
      matches === 0
        ? `${describe(instance)} does not contain items matching the given schema`
        : `Too few items match the given schema (expected at least ${minContains} but only ${matches} matched)`,
    );
  }
}

function numberOption(schema, keyword, fallback) {
  const value = get(schema, keyword, undefined);
  if (value === undefined) return fallback;
  return isPyNum(value) ? value.num : value;
}

/* --------------------------------------------------------------- objects */

export function* minProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  if (instance.size < value.num) {
    yield new ValidationError(`${describe(instance)} does not have enough properties`);
  }
}

export function* maxProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  if (instance.size > value.num) {
    yield new ValidationError(`${describe(instance)} has too many properties`);
  }
}

export function* required(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of value) {
    if (!instance.has(property)) {
      yield new ValidationError(`${describe(property)} is a required property`);
    }
  }
}

export function* properties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, subschema] of value) {
    if (instance.has(property)) {
      yield* validator.descend(instance.get(property), subschema, property, property);
    }
  }
}

export function* patternProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const [patrn, subschema] of value) {
    for (const [key, child] of instance) {
      if (search(patrn, key)) {
        yield* validator.descend(child, subschema, key, patrn);
      }
    }
  }
}

export function* propertyNames(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of instance.keys()) {
    yield* validator.descend(property, value);
  }
}

/**
 * `_utils.find_additional_properties` — note that the patterns are joined into
 * one alternation before matching, exactly as upstream does.
 */
function* findAdditionalProperties(instance, schema) {
  const declared = get(schema, 'properties', null);
  const patterns = [...(isObject(get(schema, 'patternProperties', null)) ? get(schema, 'patternProperties').keys() : [])].join('|');

  for (const property of instance.keys()) {
    if (isObject(declared) && declared.has(property)) continue;
    if (patterns && search(patterns, property)) continue;
    yield property;
  }
}

export function* additionalProperties(validator, value, instance, schema) {
