      if (!instance.has(each)) {
        yield new ValidationError(`${describe(each)} is a dependency of ${describe(property)}`);
      }
    }
  }
}

export function* dependentSchemas(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
