/**
 * Keyword implementations for the older drafts (`jsonschema._legacy_keywords`).
 *
 * Draft-3 is the odd one out: `required` lives inside `properties`, `type` may
 * contain nested schemas, and it has `divisibleBy`, `disallow` and `extends`
 * instead of `multipleOf`, `not` and `allOf`.
 */

import { ValidationError } from '../errors.mjs';
import { ensureList, get, has, isObject } from '../jtypes.mjs';
import { numGe, numGt, numLe, numLt } from '../pynum.mjs';
import { describe } from './common.mjs';

export function* typeDraft3(validator, types, instance, schema) {
  const wanted = ensureList(types);
  const allErrors = [];
  for (let index = 0; index < wanted.length; index += 1) {
    const candidate = wanted[index];
    if (validator.isType(candidate, 'object')) {
      const errors = [...validator.descend(instance, candidate, undefined, index)];
      if (errors.length === 0) return;
      allErrors.push(...errors);
    } else if (validator.isType(instance, candidate)) {
      return;
    }
  }
  yield new ValidationError(`${describe(instance)} is not of type ${wanted.map(describe).join(', ')}`, {
    context: allErrors,
  });
}

/** Draft-3 folds `required` into `properties`. */
export function* propertiesDraft3(validator, properties, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, subschema] of properties) {
    if (instance.has(property)) {
      yield* validator.descend(instance.get(property), subschema, property, property);
    } else if (get(subschema, 'required', false)) {
      yield new ValidationError(`${describe(property)} is a required property`);
    }
  }
}

export function* disallowDraft3(validator, disallow, instance, schema) {
  for (const disallowed of ensureList(disallow)) {
    const probe = new Map([['type', [disallowed]]]);
    if (validator.evolve(probe).isValid(instance)) {
      yield new ValidationError(`${describe(disallowed)} is disallowed for ${describe(instance)}`);
    }
  }
}

export function* extendsDraft3(validator, extendsValue, instance, schema) {
  if (validator.isType(extendsValue, 'object')) {
    yield* validator.descend(instance, extendsValue);
    return;
  }
  for (let index = 0; index < extendsValue.length; index += 1) {
    yield* validator.descend(instance, extendsValue[index], undefined, index);
  }
