  if (!validator.isType(instance, 'array')) return;

  if (validator.isType(items, 'array')) {
    const count = Math.min(instance.length, items.length);
    for (let index = 0; index < count; index += 1) {
      yield* validator.descend(instance[index], items[index], index, index);
    }
    return;
