/**
 * `unevaluatedProperties` / `unevaluatedItems`.
 *
 * These need to know which properties and indexes sibling keywords already
 * covered. `jsonschema` computes that with a structural walk of the schema
 * rather than by collecting real annotations, and the walk has quirks that are
 * observable in the error counts — most notably it treats `additionalProperties`
 * and `unevaluatedProperties` like `properties`, i.e. it reads *their own keys*
 * as property names. Those quirks are reproduced deliberately.
 *
 * Both keywords collapse every offending property/item into a single error.
 */

import { ValidationError } from '../errors.mjs';
import { get, has, isArray, isBool, isObject, isString } from '../jtypes.mjs';
import { search } from '../pyre.mjs';
import { describe } from './common.mjs';

const PROPERTY_KEYWORDS = ['properties', 'additionalProperties', 'unevaluatedProperties'];
const IN_PLACE_APPLICATORS = ['allOf', 'oneOf', 'anyOf'];

function range(n) {
  return Array.from({ length: n }, (_, i) => i);
}

/** Follow `$ref` / `$dynamicRef` / `$recursiveRef` and keep collecting. */
function* throughReferences(validator, instance, schema, collect) {
  const ref = get(schema, '$ref', undefined);
  if (isString(ref)) {
    const resolved = validator.resolver.lookup(ref);
    yield* collect(
      validator.evolve(resolved.contents, resolved.resolver),
      instance,
      resolved.contents,
    );
  }
  for (const keyword of ['$dynamicRef', '$recursiveRef']) {
    if (!has(schema, keyword)) continue;
    const resolved = validator.lookupDynamic(get(schema, keyword, '#'), keyword);
    if (resolved === null) continue;
    yield* collect(
      validator.evolve(resolved.contents, resolved.resolver),
      instance,
      resolved.contents,
    );
  }
}

function* throughInPlace(validator, instance, schema, collect) {
  for (const keyword of IN_PLACE_APPLICATORS) {
    const subschemas = get(schema, keyword, undefined);
    if (subschemas === undefined) continue;
    for (const subschema of subschemas) {
      // Only branches that actually succeeded contribute annotations.
      if (validator.evolve(subschema).isValid(instance)) {
        yield* collect(validator, instance, subschema);
      }
    }
  }

  if (has(schema, 'if')) {
    const ifSchema = schema.get('if');
    if (validator.evolve(ifSchema).isValid(instance)) {
      yield* collect(validator, instance, ifSchema);
      if (has(schema, 'then')) yield* collect(validator, instance, schema.get('then'));
    } else if (has(schema, 'else')) {
      yield* collect(validator, instance, schema.get('else'));
    }
  }
}

export function* findEvaluatedPropertyKeys(validator, instance, schema) {
  if (isBool(schema)) return;

  yield* throughReferences(validator, instance, schema, findEvaluatedPropertyKeys);

  for (const keyword of PROPERTY_KEYWORDS) {
    if (!has(schema, keyword)) continue;
    const value = schema.get(keyword);
    if (isBool(value)) {
      if (value) yield* instance.keys();
    } else if (isObject(value)) {
      for (const property of value.keys()) {
        if (instance.has(property)) yield property;
      }
    }
  }

  const patterns = get(schema, 'patternProperties', undefined);
  if (isObject(patterns)) {
    for (const property of instance.keys()) {
      for (const patrn of patterns.keys()) {
        if (search(patrn, property)) yield property;
      }
    }
  }

  const dependent = get(schema, 'dependentSchemas', undefined);
  if (isObject(dependent)) {
    for (const [property, subschema] of dependent) {
      if (!instance.has(property)) continue;
      yield* findEvaluatedPropertyKeys(validator, instance, subschema);
    }
  }

  yield* throughInPlace(validator, instance, schema, findEvaluatedPropertyKeys);
}

/** 2020-12 flavour: `prefixItems` + schema-shaped `items`. */
export function* findEvaluatedItemIndexes(validator, instance, schema) {
  if (isBool(schema)) return;

  yield* throughReferences(validator, instance, schema, findEvaluatedItemIndexes);

  if (has(schema, 'items')) {
    // `items` (2020-12) applies to every position past `prefixItems`, so
    // together they cover the whole array.
    yield* range(instance.length);
    return;
  }
  const prefix = get(schema, 'prefixItems', undefined);
  if (isArray(prefix)) yield* range(Math.min(prefix.length, instance.length));

  if (has(schema, 'contains')) yield* range(instance.length);

  yield* throughInPlace(validator, instance, schema, findEvaluatedItemIndexes);
}

