export function* findEvaluatedItemIndexesLegacy(validator, instance, schema) {
  if (isBool(schema)) return;

  yield* throughReferences(validator, instance, schema, findEvaluatedItemIndexesLegacy);

  if (has(schema, 'items')) {
    const items = schema.get('items');
    if (validator.isType(items, 'object')) {
