      return;
    }
    if (isArray(items)) {
      yield* range(Math.min(items.length, instance.length));
      // `additionalItems` — whatever its value — governs the tail.
      if (has(schema, 'additionalItems')) {
        for (let index = items.length; index < instance.length; index += 1) yield index;
      }
    }
  }

  if (has(schema, 'contains')) yield* range(instance.length);

  yield* throughInPlace(validator, instance, schema, findEvaluatedItemIndexesLegacy);
}

