  return function* unevaluatedProperties(validator, value, instance, schema) {
    if (!validator.isType(instance, 'object')) return;

    const evaluated = new Set(findEvaluatedPropertyKeys(validator, instance, schema));
    const offenders = [];
    for (const [property, child] of instance) {
      if (evaluated.has(property)) continue;
      for (const _ of validator.descend(child, value, property, property)) {
        offenders.push(property);
      }
    }
    if (offenders.length === 0) return;

    yield new ValidationError(
      value === false
        ? `Unevaluated properties are not allowed (${offenders.join(', ')} unexpected)`
        : `Unevaluated properties are not valid under the given schema (${offenders.join(', ')} unevaluated and invalid)`,
    );
  };
}

export function makeUnevaluatedItems(findIndexes) {
  return function* unevaluatedItems(validator, value, instance, schema) {
    if (!validator.isType(instance, 'array')) return;

    const evaluated = new Set(findIndexes(validator, instance, schema));
    const offenders = [];
    for (let index = 0; index < instance.length; index += 1) {
      if (evaluated.has(index)) continue;
      for (const _ of validator.descend(instance[index], value, index)) {
        offenders.push(instance[index]);
      }
    }
    if (offenders.length === 0) return;

    yield new ValidationError(
      `Unevaluated items are not allowed (${offenders.map(describe).join(', ')} unexpected)`,
    );
  };
}

