/** `$ref`, `$recursiveRef` and `$dynamicRef`. */

import { get, has, isObject, isString } from '../jtypes.mjs';
import { urldefrag } from '../uri.mjs';

export function* ref(validator, refValue, instance, schema) {
  const resolved = validator.resolver.lookup(refValue);
  yield* validator.descend(instance, resolved.contents, undefined, undefined, resolved.resolver);
}

/**
 * `_legacy_keywords.lookup_recursive_ref`: climb outwards through the dynamic
 * scope for as long as each enclosing resource carries `$recursiveAnchor: true`.
 */
export function lookupRecursiveRef(resolver) {
  let resolved = resolver.lookup('#');
  if (!get(resolved.contents, '$recursiveAnchor', false)) return resolved;

  for (const uri of resolver.dynamicScope()) {
    let next;
    try {
      next = resolver.lookup(uri);
    } catch {
      break;
    }
    if (!get(next.contents, '$recursiveAnchor', false)) break;
    resolved = next;
  }
  return resolved;
}

export function* recursiveRef(validator, refValue, instance, schema) {
  const resolved = lookupRecursiveRef(validator.resolver);
  yield* validator.descend(instance, resolved.contents, undefined, undefined, resolved.resolver);
}

/**
 * Resolve `$dynamicRef` against the dynamic scope: the outermost resource whose
 * `$dynamicAnchor` matches wins, falling back to a plain `$ref` lookup.
 */
export function resolveDynamicRef(resolver, refValue) {
  const fragment = urldefrag(refValue)[1];

  if (fragment !== '') {
    const scope = resolver.dynamicScope();
    for (let i = scope.length - 1; i >= 0; i -= 1) {
      let candidate;
      try {
        candidate = resolver.lookup(`${scope[i]}#${fragment}`);
      } catch {
        continue;
      }
      const anchor = get(candidate.contents, '$dynamicAnchor', undefined);
      if (isString(anchor) && anchor === fragment) return candidate;
    }
  }
  return resolver.lookup(refValue);
}

export function* dynamicRef(validator, refValue, instance, schema) {
  const resolved = resolveDynamicRef(validator.resolver, refValue);
  yield* validator.descend(instance, resolved.contents, undefined, undefined, resolved.resolver);
}

export { has, isObject };

