/**
 * The validator classes and `validator_for`.
 *
 * Mirrors `jsonschema.validators`: each draft is a class carrying a type
 * checker, a keyword table, and a rule for which keywords apply to a given
 * schema object (pre-2019 drafts ignore every sibling of `$ref`).
 */

import { UnknownType, ValidationError } from './errors.mjs';
import { isBool, isObject, isString } from './jtypes.mjs';
import {
  SPEC_DRAFT201909,
  SPEC_DRAFT202012,
  SPEC_DRAFT3,
  SPEC_DRAFT4,
  SPEC_DRAFT6,
  SPEC_DRAFT7,
  resolverForRoot,
} from './registry.mjs';
import {
  draft201909TypeChecker,
  draft202012TypeChecker,
  draft3TypeChecker,
  draft4TypeChecker,
  draft6TypeChecker,
  draft7TypeChecker,
} from './typechecker.mjs';
import { urldefrag } from './uri.mjs';
import * as kw from './keywords/common.mjs';
import * as legacy from './keywords/legacy.mjs';
import * as refs from './keywords/refs.mjs';
import {
  findEvaluatedItemIndexes,
  findEvaluatedItemIndexesLegacy,
  makeUnevaluatedItems,
  makeUnevaluatedProperties,
} from './keywords/unevaluated.mjs';

/** Every keyword in the schema applies (2019-09 onwards). */
function allKeywords(schema) {
  return schema.entries();
}

/** Pre-2019 drafts let `$ref` suppress its siblings. */
function ignoreRefSiblings(schema) {
  if (schema.has('$ref')) return [['$ref', schema.get('$ref')]];
  return schema.entries();
}

class Validator {
  constructor(schema, meta, resolver) {
    this.schema = schema;
    this.meta = meta;
    this.formatChecker = null;
    this.resolver = resolver === undefined ? resolverForRoot(schema, meta.spec) : resolver;
  }

  isType(instance, type) {
    try {
      return this.meta.typeChecker.isType(instance, type);
    } catch (error) {
      if (error.name === 'UndefinedTypeCheck') throw new UnknownType(type);
      throw error;
    }
  }

  evolve(schema, resolver) {
    return new Validator(schema, this.meta, resolver === undefined ? this.resolver : resolver);
  }

  *iterErrors(instance) {
    let schema = this.schema;
    if (schema === true) {
      schema = new Map();
    } else if (schema === false) {
      yield new ValidationError(`False schema does not allow ${kw.describe(instance)}`, {
        validator: null,
        validatorValue: null,
        instance,
        schema,
      });
      return;
    }
    if (!isObject(schema)) {
      throw new TypeError(`schema must be an object or boolean, got ${typeof schema}`);
    }

    for (const [keyword, value] of this.meta.applicableValidators(schema)) {
      const fn = this.meta.keywords.get(keyword);
      if (fn === undefined) continue;
      for (const error of fn(this, value, instance, schema)) {
        if (error.validator === undefined) {
          error.validator = keyword;
          error.validatorValue = value;
          error.instance = instance;
          error.schema = schema;
        }
        yield error;
      }
    }
  }

  *descend(instance, schema, path, schemaPath, resolver) {
    const nested =
      resolver === undefined || resolver === null
        ? this.resolver.inSubresource(schema, this.meta.spec)
        : resolver;

    for (const error of this.evolve(schema, nested).iterErrors(instance)) {
      if (path !== undefined) error.path.unshift(path);
      if (schemaPath !== undefined) error.schemaPath.unshift(schemaPath);
      yield error;
    }
  }

  isValid(instance) {
    for (const _ of this.iterErrors(instance)) return false;
    return true;
  }

  /** Used by the `unevaluated*` walk, which has to follow dynamic references. */
  lookupDynamic(refValue, keyword) {
    try {
      if (keyword === '$recursiveRef') return refs.lookupRecursiveRef(this.resolver);
      return refs.resolveDynamicRef(this.resolver, isString(refValue) ? refValue : '#');
    } catch {
      return null;
    }
  }
}

function table(entries) {
  return new Map(entries);
}

const DRAFT3_KEYWORDS = table([
  ['$ref', refs.ref],
  ['additionalItems', legacy.additionalItems],
  ['additionalProperties', kw.additionalProperties],
  ['dependencies', legacy.dependenciesDraft3],
  ['disallow', legacy.disallowDraft3],
  ['divisibleBy', kw.multipleOf],
  ['enum', kw.enum_],
  ['extends', legacy.extendsDraft3],
  ['format', kw.format],
  ['items', legacy.itemsDraft3Draft4],
  ['maxItems', kw.maxItems],
  ['maxLength', kw.maxLength],
  ['maximum', legacy.maximumDraft3Draft4],
  ['minItems', kw.minItems],
  ['minLength', kw.minLength],
  ['minimum', legacy.minimumDraft3Draft4],
  ['pattern', kw.pattern],
  ['patternProperties', kw.patternProperties],
  ['properties', legacy.propertiesDraft3],
  ['type', legacy.typeDraft3],
  ['uniqueItems', kw.uniqueItems],
]);

const DRAFT4_KEYWORDS = table([
  ['$ref', refs.ref],
  ['additionalItems', legacy.additionalItems],
  ['additionalProperties', kw.additionalProperties],
  ['allOf', kw.allOf],
  ['anyOf', kw.anyOf],
  ['dependencies', legacy.dependenciesDraft4Draft6Draft7],
  ['enum', kw.enum_],
  ['format', kw.format],
  ['items', legacy.itemsDraft3Draft4],
  ['maxItems', kw.maxItems],
  ['maxLength', kw.maxLength],
  ['maxProperties', kw.maxProperties],
  ['maximum', legacy.maximumDraft3Draft4],
  ['minItems', kw.minItems],
  ['minLength', kw.minLength],
  ['minProperties', kw.minProperties],
  ['minimum', legacy.minimumDraft3Draft4],
  ['multipleOf', kw.multipleOf],
  ['not', kw.not_],
  ['oneOf', kw.oneOf],
  ['pattern', kw.pattern],
  ['patternProperties', kw.patternProperties],
  ['properties', kw.properties],
  ['required', kw.required],
  ['type', kw.type],
  ['uniqueItems', kw.uniqueItems],
]);

const DRAFT6_KEYWORDS = table([
  ...DRAFT4_KEYWORDS,
  ['const', kw.const_],
  ['contains', legacy.containsDraft6Draft7],
  ['exclusiveMaximum', kw.exclusiveMaximum],
  ['exclusiveMinimum', kw.exclusiveMinimum],
  ['items', legacy.itemsDraft6Draft7Draft201909],
  ['maximum', kw.maximum],
  ['minimum', kw.minimum],
  ['propertyNames', kw.propertyNames],
]);

const DRAFT7_KEYWORDS = table([...DRAFT6_KEYWORDS, ['if', kw.if_]]);

const DRAFT201909_KEYWORDS = table([
  ...DRAFT7_KEYWORDS,
  ['$recursiveRef', refs.recursiveRef],
  ['contains', kw.contains],
  ['dependentRequired', kw.dependentRequired],
  ['dependentSchemas', kw.dependentSchemas],
  ['unevaluatedItems', makeUnevaluatedItems(findEvaluatedItemIndexesLegacy)],
  ['unevaluatedProperties', makeUnevaluatedProperties()],
]);
