DRAFT202012_KEYWORDS.set('$dynamicRef', refs.dynamicRef);
DRAFT202012_KEYWORDS.set('items', kw.items);
DRAFT202012_KEYWORDS.set('prefixItems', kw.prefixItems);
DRAFT202012_KEYWORDS.set('unevaluatedItems', makeUnevaluatedItems(findEvaluatedItemIndexes));

function createValidatorClass(name, meta) {
  const cls = class extends Validator {
    constructor(schema, resolver) {
      super(schema, meta, resolver);
    }
  };
  Object.defineProperty(cls, 'name', { value: name, configurable: true });
  return cls;
}

export const Draft3Validator = createValidatorClass('Draft3Validator', {
  spec: SPEC_DRAFT3,
  typeChecker: draft3TypeChecker,
  keywords: DRAFT3_KEYWORDS,
  applicableValidators: ignoreRefSiblings,
});

export const Draft4Validator = createValidatorClass('Draft4Validator', {
  spec: SPEC_DRAFT4,
  typeChecker: draft4TypeChecker,
  keywords: DRAFT4_KEYWORDS,
  applicableValidators: ignoreRefSiblings,
});

