  typeChecker: draft6TypeChecker,
  keywords: DRAFT6_KEYWORDS,
  applicableValidators: ignoreRefSiblings,
});

export const Draft7Validator = createValidatorClass('Draft7Validator', {
  spec: SPEC_DRAFT7,
  typeChecker: draft7TypeChecker,
  keywords: DRAFT7_KEYWORDS,
  applicableValidators: ignoreRefSiblings,
});

export const Draft201909Validator = createValidatorClass('Draft201909Validator', {
  spec: SPEC_DRAFT201909,
  typeChecker: draft201909TypeChecker,
  keywords: DRAFT201909_KEYWORDS,
  applicableValidators: allKeywords,
});

export const Draft202012Validator = createValidatorClass('Draft202012Validator', {
  spec: SPEC_DRAFT202012,
  typeChecker: draft202012TypeChecker,
  keywords: DRAFT202012_KEYWORDS,
  applicableValidators: allKeywords,
});

export const LATEST_VERSION = Draft202012Validator;

/** `_utils.URIDict` normalises keys through `urlsplit(...).geturl()`. */
function normalizeUri(uri) {
  const [base, fragment] = urldefrag(uri);
  return fragment === '' ? base : `${base}#${fragment}`;
}

const META_SCHEMAS = new Map(
  [
    ['http://json-schema.org/draft-03/schema#', Draft3Validator],
    ['http://json-schema.org/draft-04/schema#', Draft4Validator],
    ['http://json-schema.org/draft-06/schema#', Draft6Validator],
    ['http://json-schema.org/draft-07/schema#', Draft7Validator],
    ['https://json-schema.org/draft/2019-09/schema', Draft201909Validator],
    ['https://json-schema.org/draft/2020-12/schema', Draft202012Validator],
  ].map(([uri, cls]) => [normalizeUri(uri), cls]),
);

export const MISSING_METASCHEMA_WARNING =
  'The metaschema specified by $schema was not found. ' +
  'Using the latest draft to validate, but this will raise an error in the future.';

/**
 * `validators.validator_for`. An unrecognised `$schema` falls back to the latest
 * draft after emitting a DeprecationWarning, as upstream does.
 */
export function validatorFor(schema, onMissingMetaschema) {
  if (isBool(schema) || !isObject(schema) || !schema.has('$schema')) return LATEST_VERSION;

  const declared = schema.get('$schema');
  if (!isString(declared)) {
    throw new TypeError(`$schema must be a string, got ${typeof declared}`);
  }

  const found = META_SCHEMAS.get(normalizeUri(declared));
  if (found === undefined) {
    if (onMissingMetaschema !== undefined) onMissingMetaschema(MISSING_METASCHEMA_WARNING);
    return LATEST_VERSION;
  }
  return found;
}

