/**
 * The slice of `argparse` this program needs: long options that each take one
 * value, `--opt=value` and `--opt value` forms, unambiguous prefix matching,
 * `-h/--help`, and argparse's exact usage/error wording and exit code 2.
 */

import { basename } from 'node:path';

class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.options = [];
  }

  addArgument(name, { required = false, help = '' } = {}) {
    this.options.push({ name, dest: name.replace(/^--/, ''), required, help, metavar: name.replace(/^--/, '').toUpperCase() });
    return this;
  }

  usage() {
    const parts = this.options.map((option) =>
      option.required ? `${option.name} ${option.metavar}` : `[${option.name} ${option.metavar}]`,
    );
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  helpText() {
    const rows = [['-h, --help', 'show this help message and exit']];
    for (const option of this.options) {
      rows.push([`${option.name} ${option.metavar}`, option.help]);
    }
    const width = Math.max(...rows.map(([label]) => label.length));
    const body = rows.map(([label, text]) => `  ${label.padEnd(width)}  ${text}`).join('\n');
    return `${this.usage()}\n\noptions:\n${body}`;
  }

  error(message) {
    process.stderr.write(`${this.usage()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Resolve a `--flag` to a known option, honouring argparse prefix matching. */
  resolve(flag) {
    const known = [...this.options.map((o) => o.name), '--help'];
    if (known.includes(flag)) return flag;

    const matches = known.filter((name) => name.startsWith(flag));
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      this.error(`ambiguous option: ${flag} could match ${matches.join(', ')}`);
    }
    return null;
  }

  /** argparse accepts a `-`-prefixed token as a value only if it is a number. */
  looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-') return false;
    return !/^-\d+$|^-\d*\.\d+$/.test(token);
  }

  parse(argv) {
    const values = new Map();
    const extras = [];
    let onlyPositional = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (onlyPositional || !token.startsWith('-') || token === '-') {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        onlyPositional = true;
        continue;
      }

      const eq = token.indexOf('=');
      const flag = eq === -1 ? token : token.slice(0, eq);
      const resolved = this.resolve(flag);

      if (resolved === null) {
        extras.push(token);
        continue;
      }
      if (resolved === '--help') {
        process.stdout.write(`${this.helpText()}\n`);
        process.exit(0);
      }

      if (eq !== -1) {
        values.set(resolved, token.slice(eq + 1));
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || this.looksLikeOption(next)) {
        this.error(`argument ${resolved}: expected one argument`);
      }
      values.set(resolved, next);
      i += 1;
    }

    const missing = this.options.filter((o) => o.required && !values.has(o.name));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map((o) => o.name).join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const result = {};
    for (const option of this.options) result[option.dest] = values.get(option.name);
    return result;
  }
}

/** The parser this program declares: `--a` and `--b`, both required strings. */
export function parseArgs(argv, scriptPath) {
  const parser = new ArgumentParser(basename(scriptPath));
  parser.addArgument('--a', { required: true, help: 'instance (JSON string)' });
  parser.addArgument('--b', { required: true, help: 'schema (JSON string)' });
  return parser.parse(argv);
}

