 *
 * Picks a validator class for the schema the way `jsonschema.validators.validator_for`
 * does, then prints the class name, the boolean verdict, and the number of
 * top-level errors `iter_errors` yields.
 */

import { parseArgs } from './lib/cli.mjs';
import { loads } from './lib/json.mjs';
import { validatorFor } from './lib/validators.mjs';

const args = parseArgs(process.argv.slice(2), process.argv[1]);

const instance = loads(args.a);
const schema = loads(args.b);

// Use validator_for to get appropriate validator class
const ValidatorClass = validatorFor(schema, (message) => {
  process.stderr.write(`${process.argv[1]}: DeprecationWarning: ${message}\n`);
});
const validator = new ValidatorClass(schema); // Create instance

const result = validator.isValid(instance); // Validate
const errors = [...validator.iterErrors(instance)]; // Get errors

console.log(ValidatorClass.name);
console.log(result ? 'True' : 'False');
console.log(String(errors.length));

