#!/usr/bin/env node
/**
 * Differential harness: runs every (instance, schema) pair through the Python
 * executable and through test13.mjs and reports any divergence in stdout.
 * Not part of the deliverable — a development aid.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:url' in globalThis ? 'node:fs' : 'node:fs';

const EXE = '/workspace/dataset/test13_executable';

function run(cmd, argv) {
  try {
    return {
      out: execFileSync(cmd[0], [...cmd.slice(1), ...argv], {
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'pipe'],
      }),
      ok: true,
    };
  } catch (error) {
    return { out: error.stdout === undefined ? '' : error.stdout, ok: false };
  }
}

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));

let pass = 0;
const failures = [];
for (const [a, b] of cases) {
  const argv = ['--a', a, '--b', b];
  const py = run([EXE], argv);
  const js = run(['node', '/output/test13.mjs'], argv);

  if (py.out === js.out && py.ok === js.ok) {
    pass += 1;
  } else {
    failures.push({ a, b, py: `${py.out.trim()}${py.ok ? '' : ' [exc]'}`, js: `${js.out.trim()}${js.ok ? '' : ' [exc]'}` });
  }
}

console.log(`pass ${pass}/${cases.length}`);
for (const f of failures) {
  console.log('---');
  console.log(`  schema:   ${f.b}`);
  console.log(`  instance: ${f.a}`);
  console.log(`  python:   ${JSON.stringify(f.py)}`);
  console.log(`  node:     ${JSON.stringify(f.js)}`);
}
process.exit(failures.length === 0 ? 0 : 1);

